export interface Signal {
  index: number;
  type: 'entry' | 'exit';
  side: string;
  tag: string;
  price?: number;
  profit_pct?: number;
  win?: boolean;
}

export interface TradeRange {
  entry_index: number;
  exit_index: number;
  side: string;
  tag: string;
  entry_price: number;
  profit_pct: number | null;
  win: boolean | null;
  exit_tag: string;
}

export interface PairRawData {
  labels: string[];
  ohlc: number[][];
  price: number[];
  pair_zscore: number[];
  spread_zscore: number[];
  spread_z_a?: number[];
  spread_z_b?: number[];
  basket_z?: number[];
  basket_spread?: number[];
  regime_ok?: number[];
  spread_vol_ok?: number[];
  rolling_corr?: number[];
  vol_ratio?: number[];
  btc_mom?: number[];
  btc_atr_z?: number[];
  btc_pump?: boolean[];
  btc_dump?: boolean[];
  btc_high_vol?: boolean[];
  signals: Signal[];
  trade_ranges: TradeRange[];
  vol_ok: boolean[];
}

export interface ActiveTrade extends TradeRange {
  current_profit_pct: number;
}

export interface Decision {
  mode: 'entry' | 'exit';
  conditions: { name: string; ok: boolean; value: string }[];
  signal: string;
}

export interface FrameCandle {
  open: number;
  high: number;
  low: number;
  close: number;
  pair_z: number;
  spread_z: number;
  signal: Signal | null;
}

